/// Go: `func CompilerOptionsAffectSemanticDiagnostics(oldOptions, newOptions *core.CompilerOptions) bool`.
pub fn compiler_options_affect_semantic_diagnostics(
    old_options: Option<&CompilerOptions>,
    new_options: Option<&CompilerOptions>,
) -> bool {
    // Go: `if oldOptions == newOptions { return false }` — pointer identity;
    // two Nones are the same "nil" here.
    let same = match (old_options, new_options) {
        (None, None) => true,
        (Some(a), Some(b)) => std::ptr::eq(a, b),
        _ => false,
    };
    if same {
        return false;
    }
    let (Some(old), Some(new)) = (old_options, new_options) else {
        return true;
    };
    old.allow_importing_ts_extensions != new.allow_importing_ts_extensions
        || old.allow_umd_global_access != new.allow_umd_global_access
        || old.allow_unreachable_code != new.allow_unreachable_code
        || old.allow_unused_labels != new.allow_unused_labels
        || old.assume_changes_only_affect_direct_dependencies
            != new.assume_changes_only_affect_direct_dependencies
        || old.check_js != new.check_js
        || old.emit_decorator_metadata != new.emit_decorator_metadata
        || old.erasable_syntax_only != new.erasable_syntax_only
        || old.exact_optional_property_types != new.exact_optional_property_types
        || old.experimental_decorators != new.experimental_decorators
        || old.isolated_declarations != new.isolated_declarations
        || old.jsx != new.jsx
        || old.jsx_import_source != new.jsx_import_source
        || old.no_error_truncation != new.no_error_truncation
        || old.no_fallthrough_cases_in_switch != new.no_fallthrough_cases_in_switch
        || old.get_strict_option_value(old.no_implicit_any)
            != new.get_strict_option_value(new.no_implicit_any)
        || old.get_strict_option_value(old.no_implicit_this)
            != new.get_strict_option_value(new.no_implicit_this)
        || old.no_implicit_returns != new.no_implicit_returns
        || old.no_property_access_from_index_signature
            != new.no_property_access_from_index_signature
        || old.no_unchecked_indexed_access != new.no_unchecked_indexed_access
        || old.no_unused_locals != new.no_unused_locals
        || old.no_unused_parameters != new.no_unused_parameters
        || old.no_implicit_override != new.no_implicit_override
        || old.no_unchecked_side_effect_imports != new.no_unchecked_side_effect_imports
        || old.rewrite_relative_import_extensions != new.rewrite_relative_import_extensions
        || old.stable_type_ordering != new.stable_type_ordering
        || old.get_strict_option_value(old.strict_bind_call_apply)
            != new.get_strict_option_value(new.strict_bind_call_apply)
        || old.get_strict_option_value(old.strict_builtin_iterator_return)
            != new.get_strict_option_value(new.strict_builtin_iterator_return)
        || old.get_strict_option_value(old.strict_function_types)
            != new.get_strict_option_value(new.strict_function_types)
        || old.get_strict_option_value(old.strict_null_checks)
            != new.get_strict_option_value(new.strict_null_checks)
        || old.get_strict_option_value(old.strict_property_initialization)
            != new.get_strict_option_value(new.strict_property_initialization)
        || old.use_define_for_class_fields != new.use_define_for_class_fields
        || old.get_strict_option_value(old.use_unknown_in_catch_variables)
            != new.get_strict_option_value(new.use_unknown_in_catch_variables)
        || old.verbatim_module_syntax != new.verbatim_module_syntax
        || old.allow_synthetic_default_imports != new.allow_synthetic_default_imports
        || old.es_module_interop != new.es_module_interop
}

/// Go: `func CompilerOptionsAffectDeclarationPath(oldOptions, newOptions *core.CompilerOptions) bool`.
pub fn compiler_options_affect_declaration_path(
    old_options: Option<&CompilerOptions>,
    new_options: Option<&CompilerOptions>,
) -> bool {
    // Go: `if oldOptions == newOptions { return false }` — pointer identity;
    // two Nones are the same "nil" here.
    let same = match (old_options, new_options) {
        (None, None) => true,
        (Some(a), Some(b)) => std::ptr::eq(a, b),
        _ => false,
    };
    if same {
        return false;
    }
    let (Some(old), Some(new)) = (old_options, new_options) else {
        return true;
    };
    old.declaration_dir != new.declaration_dir
        || old.out_dir != new.out_dir
        || old.root_dir != new.root_dir
        || old.out_file != new.out_file
}

/// Go: `func CompilerOptionsAffectEmit(oldOptions, newOptions *core.CompilerOptions) bool`.
pub fn compiler_options_affect_emit(
    old_options: Option<&CompilerOptions>,
    new_options: Option<&CompilerOptions>,
) -> bool {
    // Go: `if oldOptions == newOptions { return false }` — pointer identity;
    // two Nones are the same "nil" here.
    let same = match (old_options, new_options) {
        (None, None) => true,
        (Some(a), Some(b)) => std::ptr::eq(a, b),
        _ => false,
    };
    if same {
        return false;
    }
    let (Some(old), Some(new)) = (old_options, new_options) else {
        return true;
    };
    old.assume_changes_only_affect_direct_dependencies
        != new.assume_changes_only_affect_direct_dependencies
        || old.emit_bom != new.emit_bom
        || old.emit_decorator_metadata != new.emit_decorator_metadata
        || old.declaration_dir != new.declaration_dir
        || old.experimental_decorators != new.experimental_decorators
        || old.import_helpers != new.import_helpers
        || old.inline_sources != new.inline_sources
        || old.jsx != new.jsx
        || old.jsx_import_source != new.jsx_import_source
        || old.map_root != new.map_root
        || old.module != new.module
        || old.new_line != new.new_line
        || old.no_emit_helpers != new.no_emit_helpers
        || old.no_emit_on_error != new.no_emit_on_error
        || old.out_dir != new.out_dir
        || old.preserve_const_enums != new.preserve_const_enums
        || old.remove_comments != new.remove_comments
        || old.react_namespace != new.react_namespace
        || old.root_dir != new.root_dir
        || old.strip_internal != new.strip_internal
        || old.source_root != new.source_root
        || old.target != new.target
        || old.ts_build_info_file != new.ts_build_info_file
        || old.use_define_for_class_fields != new.use_define_for_class_fields
        || old.verbatim_module_syntax != new.verbatim_module_syntax
        || old.always_strict != new.always_strict
        || old.downlevel_iteration != new.downlevel_iteration
        || old.es_module_interop != new.es_module_interop
        || old.out_file != new.out_file
}

